package mrpapermoon.whisper.contacts.dbimport androidx.room.Entityimport androidx.room.PrimaryKeyimport mrpapermoon.whisper.entity.UserColorimport mrpapermoon.whisper.entity.UserIcon@Entity(tableName = ContactEntity.TABLE_NAME)data class ContactEntity(	@PrimaryKey	val whispererId: String,	val name: String,	val color: UserColor,	val icon: UserIcon,) {	companion object {		internal const val TABLE_NAME = "contacts"	}}